<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Pterodactyl\Models\Dezerx\DiscordBot; class BotSettings { public const CATALOGUE = [ 'servers' => ['group' => 'Servers', 'emoji' => '🖥️', 'description' => 'Every server you can reach, with live status and resources.'], 'controlpanel' => ['group' => 'Servers', 'emoji' => '🎛️', 'description' => 'Live console, resources and power controls for one server.'], 'power' => ['group' => 'Servers', 'emoji' => '⚡', 'description' => 'Start, stop, restart or kill a server.'], 'command' => ['group' => 'Servers', 'emoji' => '⌨️', 'description' => 'Send a command to a server\'s console.'], 'backups' => ['group' => 'Data', 'emoji' => '💾', 'description' => 'Create, lock, unlock, download and delete backups.'], 'connect' => ['group' => 'Data', 'emoji' => '🔗', 'description' => 'Addresses, subdomains and SFTP details for a server.'], 'activity' => ['group' => 'Data', 'emoji' => '📜', 'description' => 'The latest things that happened on a server.'], 'billing' => ['group' => 'Data', 'emoji' => '💳', 'description' => 'Plan, price, renewal date and unpaid invoices for a server.'], 'alerts' => ['group' => 'Alerts', 'emoji' => '🔔', 'description' => 'Ping a role when a server runs hot or goes down.'], 'account' => ['group' => 'Account', 'emoji' => '👤', 'description' => 'Which panel account the bot is acting as.'], 'unlink' => ['group' => 'Account', 'emoji' => '🔌', 'description' => 'Disconnect this Discord account from the panel.'], 'help' => ['group' => 'Account', 'emoji' => '👋', 'description' => 'What this bot can do.'], ]; public const ALWAYS_ON = ['help']; public const BARS = ['squares', 'circles', 'blocks']; public const VISIBILITY = ['private', 'public', 'choice']; public const POWER_ACTIONS = ['start', 'restart', 'stop', 'kill']; public const MAX_USERS = 25; public const DESIGN = [ 'accent' => '', 'banner' => true, 'logos' => true, 'bars' => 'squares', 'footer' => '', 'console_lines' => 14, 'bar_length' => 16, 'visibility' => 'private', 'console_image' => false, 'console_font' => 13, ]; public static function available(DiscordBot $bot, string $command): bool { if (in_array($command, BotConfig::disabledCommands(), true)) { return false; } return match ($command) { 'billing' => BotConfig::billingEnabled(), 'alerts' => BotConfig::alertsEnabled(), 'unlink' => $bot->isGlobal(), default => array_key_exists($command, self::CATALOGUE), }; } public static function enabled(DiscordBot $bot, string $command): bool { if (!self::available($bot, $command)) { return false; } if (in_array($command, self::ALWAYS_ON, true)) { return true; } return (bool) ($bot->settings['commands'][$command]['enabled'] ?? true); } public static function active(DiscordBot $bot): array { return array_values(array_filter(array_keys(self::CATALOGUE), fn (string $command) => self::enabled($bot, $command))); } public static function roles(DiscordBot $bot, string $command): array { return array_values(array_filter( array_map('strval', (array) ($bot->settings['commands'][$command]['roles'] ?? [])), fn (string $id) => ctype_digit($id), )); } public static function commands(DiscordBot $bot): array { $out = []; foreach (self::CATALOGUE as $name => $meta) { $out[] = [ 'name' => $name, 'group' => $meta['group'], 'emoji' => $meta['emoji'], 'description' => $meta['description'], 'available' => self::available($bot, $name), 'enabled' => self::enabled($bot, $name), 'stored' => in_array($name, self::ALWAYS_ON, true) || (bool) ($bot->settings['commands'][$name]['enabled'] ?? true), 'locked' => in_array($name, self::ALWAYS_ON, true), 'roles' => $bot->isGlobal() ? [] : self::roles($bot, $name), ]; if ($name === 'power') { $out[array_key_last($out)]['actions'] = self::powerActions($bot); } } return $out; } public static function users(DiscordBot $bot): array { return array_values(array_filter( (array) ($bot->settings['users'] ?? []), fn ($user) => is_array($user) && ctype_digit((string) ($user['id'] ?? '')), )); } public static function userIds(DiscordBot $bot): array { return array_map(fn (array $user) => (string) $user['id'], self::users($bot)); } public static function design(?DiscordBot $bot): array { return self::normaliseDesign((array) ($bot?->settings['design'] ?? [])); } public static function normaliseDesign(array $input): array { $accent = trim((string) ($input['accent'] ?? '')); $bars = (string) ($input['bars'] ?? self::DESIGN['bars']); $visibility = (string) ($input['visibility'] ?? self::DESIGN['visibility']); return [ 'accent' => preg_match('/^#?([0-9a-f]{6})$/i', $accent, $match) === 1 ? '#' . strtolower($match[1]) : '', 'banner' => (bool) ($input['banner'] ?? self::DESIGN['banner']), 'logos' => (bool) ($input['logos'] ?? self::DESIGN['logos']), 'bars' => in_array($bars, self::BARS, true) ? $bars : self::DESIGN['bars'], 'footer' => mb_substr(trim((string) preg_replace('/\s+/', ' ', (string) ($input['footer'] ?? ''))), 0, 80), 'console_lines' => max(5, min(30, (int) ($input['console_lines'] ?? self::DESIGN['console_lines']))), 'bar_length' => max(5, min(30, (int) ($input['bar_length'] ?? self::DESIGN['bar_length']))), 'visibility' => in_array($visibility, self::VISIBILITY, true) ? $visibility : self::DESIGN['visibility'], 'console_image' => (bool) ($input['console_image'] ?? self::DESIGN['console_image']), 'console_font' => max(ConsoleImage::FONT_MIN, min(ConsoleImage::FONT_MAX, (int) ($input['console_font'] ?? self::DESIGN['console_font']))), ]; } public static function visibility(?DiscordBot $bot): string { return (string) (self::design($bot)['visibility'] ?? 'private'); } public static function normaliseCommands(array $input, bool $roles): array { $out = []; foreach (array_keys(self::CATALOGUE) as $name) { $row = (array) ($input[$name] ?? []); $out[$name] = [ 'enabled' => in_array($name, self::ALWAYS_ON, true) || (bool) ($row['enabled'] ?? true), 'roles' => $roles ? array_slice(array_values(array_unique(array_filter(array_map('strval', (array) ($row['roles'] ?? [])), 'ctype_digit'))), 0, 25) : [], ]; if ($name === 'power') { $actions = array_values(array_intersect(self::POWER_ACTIONS, array_map('strval', (array) ($row['actions'] ?? self::POWER_ACTIONS)))); $out[$name]['actions'] = $actions === [] ? self::POWER_ACTIONS : $actions; } } return $out; } public static function powerActions(DiscordBot $bot): array { $actions = array_values(array_intersect(self::POWER_ACTIONS, array_map('strval', (array) ($bot->settings['commands']['power']['actions'] ?? self::POWER_ACTIONS)))); return $actions === [] ? self::POWER_ACTIONS : $actions; } public static function save(DiscordBot $bot, ?array $design = null, ?array $commands = null, ?array $users = null): void { $settings = (array) ($bot->settings ?? []); if ($users !== null) { $settings['users'] = array_slice(array_values($users), 0, self::MAX_USERS); } if ($design !== null) { $settings['design'] = self::normaliseDesign($design); } if ($commands !== null) { $settings['commands'] = self::normaliseCommands($commands, !$bot->isGlobal()); } $bot->settings = $settings; $bot->save(); } } 